entries[49799] = { ["name"] = "Zerfetzen", ["text"] = "30 Energie Nahkampfreichweite\nSofort\nBenötigt Katzengestalt\nFinishing-Move, der Schaden im Lauf der Zeit verursacht. Der Schaden erhöht sich pro Combopunkt sowie durch Eure Angriffskraft:\n1 Punkt: [(30 + 67 * 1 + 0.01 * Attack power) * 6 ] Schaden im Verlauf von 12 sec.\n2 Punkte: [(30 + 67 * 2 + 0.02 * Attack power) * 6 ] Schaden im Verlauf von 12 sec.\n3 Punkte: [(30 + 67 * 3 + 0.03 * Attack power) * 6 ] Schaden im Verlauf von 12 sec.\n4 Punkte: [(30 + 67 * 4 + 0.04 * Attack power) * 6 ] Schaden im Verlauf von 12 sec.\n5 Punkte: [(30 + 67 * 5 + 0.05 * Attack power) * 6 ] Schaden im Verlauf von 12 sec." }
