entries[49802] = { ["name"] = "Zerfleddern", ["text"] = "35 Energie Nahkampfreichweite\nSofort 10 sek. Abklingzeit\nBenötigt Katzengestalt\nFinishing-Move, der Schaden verursacht und den Gegner betäubt. Unterbricht zudem 3 sec lang das Zauberwirken von Nichtspieler-Zielen. Verursacht mehr Schaden und hält pro Combopunkt länger an:\n1 Punkt: (158 * 1 + 66 + Mainhand weapon min damage)-(158 * 1 + 66 + Mainhand weapon max damage) Schaden, 1 Sek.\n2 Punkte: (158 * 2 + 66 + Mainhand weapon min damage)-(158 * 2 + 66 + Mainhand weapon max damage) Schaden, 2 Sek.\n3 Punkte: (158 * 3 + 66 + Mainhand weapon min damage)-(158 * 3 + 66 + Mainhand weapon max damage) Schaden, 3 Sek.\n4 Punkte: (158 * 4 + 66 + Mainhand weapon min damage)-(158 * 4 + 66 + Mainhand weapon max damage) Schaden, 4 Sek.\n5 Punkte: (158 * 5 + 66 + Mainhand weapon min damage)-(158 * 5 + 66 + Mainhand weapon max damage) Schaden, 5 Sek." }
