entries[50397] = { ["name"] = "Lichritter", ["text"] = "Sofort\nErfüllt Euch mit unheiligen Energien, um 30 sec lang untot zu werden. Im untoten Zustand seid Ihr immun gegenüber Bezauberungs-, Furcht- und Schlafeffekten." }
