entries[50400] = { ["name"] = "Lous Kanufahrt", ["text"] = "5 Meter Reichweite\nSofort\nFährt in Lous Kanu zum Ganovenlager!" }
entries[50401] = { ["name"] = "Schneidendes Eis", ["text"] = "10 Meter Reichweite\nSofort\nEure Runenwaffe verursacht 2% zusätzlichen Waffenschaden als Frostschaden.\n(8ms Abklingzeit)" }
entries[50402] = { ["name"] = "Rösten", ["text"] = "45 Meter Reichweite\nSofort\nVerbrennt einen Gegner und fügt dann zusätzlich 12 sec lang alle 3 Sek. Feuerschaden zu." }
entries[50403] = { ["name"] = "Knochen werfen", ["text"] = "50 Meter Reichweite\nWirken in 0.5 sek.\nWirft einen Knochen auf einen Gegner und verursacht 525 to 675 Schaden." }
entries[50405] = { ["name"] = "Geschmiedeter Donner", ["text"] = "10 - 70 Meter Reichweite\nWirken in 1 sek.\nVerursacht 2625 to 3375 Naturschaden bei einem Gegner." }
entries[50406] = { ["name"] = "Gefrorene Runenwaffe", ["text"] = "Unbegrenzte Reichweite\nSofort\nErfüllt Eure Runenwaffe mit Frost. Basierend auf dem Waffentempo wird zusätzlich Frostschaden verursacht. Hält 10 Min. lang an. Zudem besteht eine Chance, dass Ziele 20 sec lang 2% mehr Frostschaden erleiden. Dieser Effekt ist bis zu 10-mal stapelbar." }
entries[50407] = { ["name"] = "Einhüllende Flammen", ["text"] = "Unbegrenzte Reichweite\nSofort\nFeuert eine Raketensalve auf das Ziel und alle in der Nähe des Ziels ab." }
entries[50408] = { ["name"] = "Einhüllende Flammen", ["text"] = "2500 Mana 40 Meter Reichweite\nSofort 1 sek. Abklingzeit\nWirft eine Feuerkugel auf Geißeldiener in Galakronds Ruhestätte." }
entries[50409] = { ["name"] = "Einhüllende Flammen", ["text"] = "2000 Mana 80 Meter Reichweite\nSofort 1 sek. Abklingzeit\nWirft eine tödliche Feuerkugel auf Geißeldiener in Galakronds Ruhestätte." }
entries[50410] = { ["name"] = "Hauerstoß", ["text"] = "Nahkampfreichweite\nNächster Nahkampf\nFügt einem Gegner 150 normalen Schaden zu und stößt ihn zurück." }
entries[50411] = { ["name"] = "Benommen", ["text"] = "100 Meter Reichweite\nSofort\nBenommen." }
entries[50412] = { ["name"] = "Dornen", ["text"] = "400 Mana 30 Meter Reichweite\nSofort 1 min Abklingzeit\nAus dem befreundeten Ziel sprießen Dornen, die jedem Angreifer 140 to 200 Naturschaden zufügen. Hält 30 sec lang an." }
entries[50413] = { ["name"] = "Magnataurenstürmen", ["text"] = "Sofort\nErhöht das Bewegungstempo des Zaubernden 10 sec lang um 60%, und lässt ihn bei seinen ersten drei Angriffen zusätzlich 350 Schaden zufügen." }
entries[50414] = { ["name"] = "Blutfluch", ["text"] = "20 Meter Reichweite\nWirken in 1.5 sek.\nErhöht den erlittenen körperlichen Schaden von in der Nähe befindlichen Feinden 8 sec lang um 500." }
entries[50415] = { ["name"] = "Todeszauber", ["text"] = "Sofort\nRuft einen Bernsteindrachen hinab, auf den Ihr aufsitzen und in die Schlacht fliegen könnt." }
entries[50416] = { ["name"] = "Frostbeißerwaffe", ["text"] = "Wirken in 2 sek.\nVerzaubert Eure Waffe mit 'Frostbeißer', der 95 to 105 Frostschaden verursacht und das Bewegungstempo des Ziels 3 sec lang um 30% verringert, wenn Ihr Nahkampfschaden verursacht. Hält 8 sec lang an." }
