entries[50420] = { ["name"] = "Wutanfall", ["text"] = "Sofort\nErhöht 5 min lang das Angriffstempo des Zaubernden um 30% und den von ihm zugefügten körperlichen Schaden um 10%." }
entries[50421] = { ["name"] = "Blutgeruch", ["text"] = "Sofort\nEuer nächster erfolgreicher Nahkampfangriff erzeugt 10 Runenmacht. Der Effekt hält 20 sec lang an." }
