entries[50424] = { ["name"] = "Mal des Blutes", ["text"] = "Unbegrenzte Reichweite\nSofort\nBelegt einen Feind mit einem Mal des Blutes. Wenn dieser Feind Schaden verursacht, wird sein Ziel um 4% der eigenen maximalen Gesundheit geheilt. Hält 20 sec lang an." }
entries[50425] = { ["name"] = "Verdünnte astrale Essenz", ["text"] = "8% von Grundmana 30 Meter Reichweite\nSofort\nErmöglicht es Euch, 30 sec lang geringe Unsichtbarkeit zu entdecken, ohne Hirnschäden zu erleiden... wahrscheinlich.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt." }
entries[50426] = { ["name"] = "Bezwinger von Wyrmruh rufen", ["text"] = "Sofort\nRuft einen Bezwinger des Wyrmruhtempels herab, um aufzusitzen und in die Schlacht zu reiten. Kann nur im Wyrmruhtempel, der Dracheneiswüste, Galakronds Ruhestätte oder der Serpentine benutzt werden." }
entries[50427] = { ["name"] = "Wasserelementarverbindung", ["text"] = "Wirken in 1 sek.\nReagenzien:\nWasserelementarverbindung (2)\nKombiniert 3 Wasserelementarverbindungen, um eine Verbindung zur Wasserebene herzustellen." }
