entries[50447] = { ["name"] = "Blutige Vergeltung", ["text"] = "Sofort\nGewährt Euch nach dem Erzielen eines kritischen Treffers mit einem automatischen Angriff, einem Zauber oder einer Fähigkeit 30 sec lang einen Bonus von 1% auf den von Euch verursachten körperlichen Schaden. Dieser Effekt ist bis zu 3-mal stapelbar." }
