entries[50452] = { ["name"] = "Blutwurm", ["text"] = "30 Meter Reichweite\nSofort 5 min Abklingzeit\nErschafft einen Blutwurm, der nahe Ziele angreift. Der Zaubernde erhält Gesundheit, wenn der Blutwurm Schaden verursacht. Hält 20 sec lang an." }
