entries[50455] = { ["name"] = "Schattenblitz", ["text"] = "90 Mana 60 Meter Reichweite\nWirken in 2 sek.\nSchleudert einen Blitz aus dunkler Magie auf einen Feind und verursacht Schattenschaden." }
