entries[50459] = { ["name"] = "Kälte", ["text"] = "30 Meter Reichweite\nSofort\nIst Eure Frostpräsenz aktiv, während Ihr einen Treffer erleidet, besteht eine Chance von 101%, dass das Bewegungstempo Eures Angreifers 5 sec lang um 10% verringert sowie die Zeit zwischen seinen Angriffen um 10% erhöht wird." }
entries[50461] = { ["name"] = "Antimagisches Feld", ["text"] = "Kanalisiert (Wirken in 30 sek.)\nPlatziert ein großes, ortsgebundenes, antimagisches Feld, das den erlittenen Zauberschaden aller darin befindlichen Gruppen- oder Schlachtzugsmitglieder um 75% verringert. Das antimagische Feld hält 10 sec lang an, oder bis (10000 + 2 * Attack power) Zauberschaden absorbiert wurden." }
entries[50462] = { ["name"] = "Antimagisches Feld", ["text"] = "1 Unheilige Rune Unbegrenzte Reichweite\nSpontanzauber 20 sek. Abklingzeit\nPlatziert ein großes, ortsgebundenes, antimagisches Feld, in dem alle Gruppenmitglieder geschützt sind. Das antimagische Feld absorbiert 75% des vom nächsten schädlichen Zauber verursachten Schaden. Absorbiert eine begrenzte Schadensmenge." }
